\delta\beta_{ij}
&=-\frac{\sqrt q}{\sqrt{E_{ij}}}
\bigl(b_l^{(k)}h_k+b_k^{(l)}h_l\bigr)
=\sqrt{E_{ij}}B_{ij}.
\end{align*}
Equation \eqref{eq:Bv-first} consequently implies
